crate::gir::owned::release!(DeviceManager, |object| {
    // SAFETY: on frida-core's thread, with an instance of DeviceManager; the async form
    // with no callback starts the release and frees its own state when done.
    unsafe {
        frida_sys::frida_device_manager_close(
            object.cast(),
            std::ptr::null_mut(),
            None,
            std::ptr::null_mut(),
        );
    }
});

impl crate::gir::Owned<DeviceManager> {
    /// Closes the device manager, releasing all resources. The instance must
    /// not be used afterwards.
    ///
    /// Calls `frida_device_manager_close_sync`.
    ///
    /// # Errors
    ///
    /// - frida-core's error, if the call fails.
    /// - [`ErrorKind::Cancelled`](crate::gir::ErrorKind::Cancelled), if `cancellable` is cancelled.
    ///
    /// Consumes the owner, and returns the error that dropping it would discard. Unlike
    /// dropping it, this waits for the release to finish.
    pub fn close(
        self,
        cancellable: Option<&crate::gir::Cancellable>,
    ) -> Result<(), crate::gir::Error> {
        self.keep().close(cancellable)
    }
}
